                  <div className="note">All required fields are marked with an asterisk.</div>
                </div>

                {submitted && Object.keys(errors).length === 0 ? (
                  <div className="success" role="status">
                    Thanks — your message is ready to send.
                  </div>
                ) : null}
              </form>
            </main>
          </div>
        );
      }

      ReactDOM.createRoot(document.getElementById("root")).render(<SupportForm />);
    </script>
