     <script type="text/babel">
       const { useMemo, useState } = React;

       const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
       const phonePattern = /^\+?[0-9\s().-]{7,20}$/;

       function Field({ id, label, required, helperText, error, children }) {
         return (
           <div className="form-field">
             <label htmlFor={id}>
               {label}
               {required ? <span className="required">*</span> : null}
             </label>
             {children}
             {helperText ? <p className="helper-text">{helperText}</p> : null}
             <p className="error-message" aria-live="polite">
               {error}
             </p>
           </div>
         );
       }

       function SupportForm() {
         const [values, setValues] = useState({
           fullName: "",
           email: "",
           phone: "",
         });
         const [touched, setTouched] = useState({});
         const [submitted, setSubmitted] = useState(false);

         const errors = useMemo(() => {
           const next = {};

           if (!values.fullName.trim()) {
             next.fullName = "Full name is required.";
           }

           if (!values.email.trim()) {
             next.email = "Email address is required.";
           } else if (!emailPattern.test(values.email.trim())) {
             next.email = "Enter a valid email address.";
           }

           if (values.phone.trim() && !phonePattern.test(values.phone.trim())) {
             next.phone = "Enter a valid phone number or leave it blank.";
           }

           return next;
         }, [values]);

