     <script type="text/babel">
       const { useMemo, useState } = React;

       const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
       const phonePattern = /^\+?[0-9\s().-]{7,20}$/;

       function Field({ id, label, required, helperText, error, children }) {
         return (
           <div className="form-field">
             <label htmlFor={id}>
               {label}
               {required ? <span className="required">*</span> : null}
             </label>
             {children}
             {helperText ? (
               <p className="helper-text" id={`${id}-help`}>
                 {helperText}
               </p>
             ) : null}
             <p className="error-message" id={`${id}-error`} aria-live="polite">
               {error}
             </p>
           </div>
         );
       }

       function SupportForm() {
         const [values, setValues] = useState({
           fullName: "",
           email: "",
           phone: "",
         });
         const [touched, setTouched] = useState({});
         const [submitted, setSubmitted] = useState(false);
         const [success, setSuccess] = useState(false);

         const errors = useMemo(() => {
           const next = {};

           if (!values.fullName.trim()) {
             next.fullName = "Full name is required.";
           }

           if (!values.email.trim()) {
             next.email = "Email address is required.";
           } else if (!emailPattern.test(values.email.trim())) {
             next.email = "Enter a valid email address.";
           }

           if (values.phone.trim() && !phonePattern.test(values.phone.trim())) {
             next.phone = "Enter a valid phone number or leave it blank.";
           }

           return next;
         }, [values]);

         const showError = (field) => (touched[field] || submitted ? errors[field] || "" : "");

         const update = (field) => (event) => {
           setSuccess(false);
           setValues((current) => ({ ...current, [field]: event.target.value }));
         };

         const blur = (field) => () => {
           setTouched((current) => ({ ...current, [field]: true }));
         };

         const handleSubmit = (event) => {
           event.preventDefault();
           setSubmitted(true);

           if (Object.keys(errors).length > 0) {
             return;
           }

           setValues({ fullName: "", email: "", phone: "" });
           setTouched({});
           setSubmitted(false);
           setSuccess(true);
         };

         return (
           <div className="page">
             <main className="card">
               <header className="card-header">
                 <p className="eyebrow">Support</p>
                 <h1>Contact our team</h1>
                 <p className="subtitle">
                   Send us your details and we&apos;ll get back to you as soon as possible.
                 </p>
               </header>

               <form onSubmit={handleSubmit} noValidate>
                 <Field id="fullName" label="Full name" required error={showError("fullName")}>
                   <input
                     id="fullName"
                     name="fullName"
                     type="text"
                     required
                     autoComplete="name"
                     value={values.fullName}
                     onChange={update("fullName")}
                     onBlur={blur("fullName")}
                     className={showError("fullName") ? "invalid" : ""}
                     placeholder="Jane Doe"
                     aria-invalid={Boolean(showError("fullName"))}
                     aria-describedby="fullName-error"
                   />
                 </Field>

                 <Field id="email" label="Email address" required error={showError("email")}>
                   <input
                     id="email"
                     name="email"
                     type="email"
                     required
                     autoComplete="email"
                     value={values.email}
                     onChange={update("email")}
                     onBlur={blur("email")}
                     className={showError("email") ? "invalid" : ""}
                     placeholder="jane@example.com"
                     aria-invalid={Boolean(showError("email"))}
                     aria-describedby="email-error"
                   />
                 </Field>

                 <Field
                   id="phone"
                   label="Phone number"
                   helperText="Optional: include digits only, spaces, parentheses, dots, or dashes. You may also start with + for an international number."
                   error={showError("phone")}
                 >
                   <input
                     id="phone"
                     name="phone"
                     type="tel"
                     autoComplete="tel"
                     value={values.phone}
                     onChange={update("phone")}
                     onBlur={blur("phone")}
                     className={showError("phone") ? "invalid" : ""}
                     placeholder="+1 (555) 123-4567"
                     aria-invalid={Boolean(showError("phone"))}
                     aria-describedby="phone-help phone-error"
                   />
                 </Field>

                 <div className="actions">
                   <button type="submit">Submit request</button>
                   <div className="note">All required fields are marked with an asterisk.</div>
                 </div>

                 {success ? (
                   <div className="success" role="status">
                     Thanks — your message is ready to send.
                   </div>
                 ) : null}
               </form>
             </main>
           </div>
')
